effect.shader:
float SCurve(float x){
x = x * 2.0 - 1.0;
return -x * abs(x) * 0.5 + x + 0.5;
}
vec4 BlurH(sampler2D source, vec2 uv, float radius, float sizeX){
if (radius < 1.0) return texture2DCv(source, uv);
float width = 1.0 / max(sizeX, 1.0);
vec3 C = vec3(0.0);
float divisor = 0.0;
const int MAX_R = 128;
float rad = clamp(radius, 0.0, float(MAX_R));
for (int i = -MAX_R; i <= MAX_R; i++){
float x = float(i);
if (abs(x) > rad) continue;
float w = SCurve(1.0 - (abs(x) / max(rad, 1e-3)));
vec2 o = vec2(x * width, 0.0);
C += texture2DCv(source, clamp(uv + o, 0.0, 1.0)).rgb * w;
divisor += w;
}
return vec4(C / max(divisor, 1e-6), 1.0);
}
void main(){
vec2 uv = acScreenNorm;
vec3 src = texture2DCv(inputImg.texture, uv).rgb;
float thresh = THRESH;
float b = dot(src, vec3(0.2126, 0.7152, 0.0722));
vec3 bright = (b > thresh) ? src : vec3(0.0);
vec4 blurredSrc = BlurH(inputImg.texture, uv, RADIUS, SIZEX);
vec3 blurredBright = blurredSrc.rgb * step(thresh, b);
vec3 outc = src * BASE_GAIN + blurredBright * BLUR_GAIN;
outc = pow(max(outc, 0.0), vec3(GAMMA));
gl_FragColor = vec4(outc, 1.0);
}
